#!/bin/bash
set -eo pipefail
umask 077
test "$(id -un)" = sunyiq
for parent in / /data1 /data1/home /data1/home/sunyiq; do
  test -d "$parent"
  test ! -L "$parent"
  test "$(readlink -e "$parent")" = "$parent"
done
test ! -e '/data1/home/sunyiq/china_us_result_identity_20261007_001'
test ! -L '/data1/home/sunyiq/china_us_result_identity_20261007_001'
mkdir '/data1/home/sunyiq/china_us_result_identity_20261007_001'
mkdir '/data1/home/sunyiq/china_us_result_identity_20261007_001/src' '/data1/home/sunyiq/china_us_result_identity_20261007_001/contracts' '/data1/home/sunyiq/china_us_result_identity_20261007_001/logs'
set -o noclobber
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_result_identity_20261007_001/src/diagnose_compute_identity_v1.py'
printf '%s  %s\n' '09b692b5da59a7b493ee155f20824ac21c4f38fd1a85f7db483871ab0b8f4b6e' '/data1/home/sunyiq/china_us_result_identity_20261007_001/src/diagnose_compute_identity_v1.py' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_result_identity_20261007_001/contracts/US_SAVED_RESULTS_CONTRACT_v1.json'
printf '%s  %s\n' '669cc85f7b3cd1352a0ec26d3410d57496a61644de78e93a826bc4c2295f7609' '/data1/home/sunyiq/china_us_result_identity_20261007_001/contracts/US_SAVED_RESULTS_CONTRACT_v1.json' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_result_identity_20261007_001/node_identity_v1.sbatch'
printf '%s  %s\n' 'a115bbb25d5bbea6aaa18e02558438c66f321925a47619610bbf4287bf79e82f' '/data1/home/sunyiq/china_us_result_identity_20261007_001/node_identity_v1.sbatch' | sha256sum -c -
job=$(sbatch --parsable '/data1/home/sunyiq/china_us_result_identity_20261007_001/node_identity_v1.sbatch')
case "$job" in ''|*[!0-9]*) printf 'UNEXPECTED_JOB_RECEIPT\n' >&2; exit 1;; esac
printf '%s\n' "$job" > '/data1/home/sunyiq/china_us_result_identity_20261007_001/job_id.txt'
printf 'NODE_IDENTITY_ROOT=/data1/home/sunyiq/china_us_result_identity_20261007_001\nNODE_IDENTITY_JOB_ID=%s\nNODE_IDENTITY_SUBMITTED_ONCE\n' "$job"
